      'Scores cannot outrun their evidence. Automated signals cap at 69, model judges at 79, one-human or disputed evidence at 89, and blocking factual, source, safety, rights, privacy, discipline, or missing-deliverable failures cap below publishable. Per-review coverage and duplicate-review checks prevent a partial or repeated second reviewer from creating independent validation.',
      'Controlled comparisons now predeclare every case, bind exact candidate/control identities, reject reused trials, seeds, and output pairs, retain failures and all-attempt cost/latency, and report paired score, speed, and compiler-burden intervals. Every numeric score must come from a byte-verified scorecard matching the exact source, artifact, rubric, dimensions, and evidence tier.',
      'Scion promotion now consumes this same ruler. A candidate must beat its exact control with positive held-out intervals in five declared domains, complete two-instructor blind review for every trial with a Wilson lower bound above 0.5, and show a strictly lower compiler-call interval. Legacy 99/A package grades and hand-shaped win counts cannot satisfy the gate.',
      'This release strengthens evaluation, not model weights. Hosted Scion remains base-only; approved training pairs, qualified v1 held-out adapter wins, and qualifying four-profile device/speed results remain zero. The retained source campaign still measures base-only Gemma at 62/96 admitted atoms before recovery (63/96 after one bounded compiler recovery) versus 91/96 for GPT-5.4-mini.',
